import mermaid from 'mermaid'
import { ensureMermaid } from '../mermaid/renderMermaid'

/**
 * Diagram Guardrail & Validation Module
 *
 * Enforces security sanitization, syntax validation, and layout safety
 * for both Draw.io XML and Mermaid code outputs generated by ARA Assistant.
 */

const INJECTION_PATTERNS: RegExp[] = [
  /ignore\s+(all\s+|any\s+)?(previous|prior|above)\s+(instructions|directives|rules|prompts)/i,
  /disregard\s+(all\s+|any\s+)?(previous|prior|above)\s+(instructions|directives|rules)/i,
  /system\s+prompt\s+(override|reveal|leak|bypass|injection)/i,
  /\b(?:jailbreak|dan\s+mode|developer\s+mode\s+enabled)\b/i,
  /you\s+are\s+now\s+(unrestricted|in\s+god\s+mode|unfiltered)/i,
  /forget\s+(all\s+|your\s+)?instructions/i,
]

/**
 * Scan user input prompt for malicious prompt injection or override patterns.
 */
export function checkPromptInjection(prompt: string): { safe: boolean; reason?: string } {
  const trimmed = prompt.trim()
  if (!trimmed) return { safe: true }
  for (const pat of INJECTION_PATTERNS) {
    if (pat.test(trimmed)) {
      return {
        safe: false,
        reason:
          'Security Notice: Prompt matches restricted instruction-override patterns and was blocked.',
      }
    }
  }
  return { safe: true }
}

/**
 * Recover a Mermaid diagram from AI chat text when the model answered with a
 * fenced code block instead of calling the generation tool (the canvas only
 * updates through tools). Returns the last fenced block (newest diagram wins)
 * plus its raw fenced text; callers validate the code before applying it.
 */
export function extractMermaidFromChat(text: string): { code: string; block: string } | null {
  const blocks = [...text.matchAll(/```(?:mermaid)?[^\S\n]*\n([\s\S]*?)```/gi)]
  for (let i = blocks.length - 1; i >= 0; i--) {
    const code = blocks[i]?.[1]?.trim()
    const block = blocks[i]?.[0]
    if (code && block) return { code, block }
  }
  return null
}

/**
 * Clean and sanitize Mermaid code:
 * 1. Strips markdown fences if model returned ```mermaid ... ```
 * 2. Sanitizes dangerous script tags or javascript pseudo-protocols
 * 3. Auto-repairs common syntax glitches (e.g. unquoted labels with parentheses)
 * 4. Validates syntax using mermaid.parse()
 */
export async function validateAndSanitizeMermaid(
  rawCode: string,
): Promise<{ valid: boolean; code: string; error?: string }> {
  ensureMermaid()

  // 1. Strip markdown code fences if wrapped
  let cleaned = rawCode.trim()
  cleaned = cleaned.replace(/^```(?:mermaid)?\s*\n?/i, '')
  cleaned = cleaned.replace(/\n?```\s*$/i, '')
  cleaned = cleaned.trim()

  // 2. Security guardrail: strip <script> tags and javascript: protocol
  cleaned = cleaned.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
  cleaned = cleaned.replace(/javascript\s*:/gi, 'about:blank#blocked')
  cleaned = cleaned.replace(/on\w+\s*=\s*["'][^"']*["']/gi, '')

  if (!cleaned) {
    return {
      valid: false,
      code: '',
      error: 'Empty Mermaid diagram code.',
    }
  }

  // 3. Header fallback if model omitted diagram type
  const hasHeader =
    /^(?:flowchart|graph|sequenceDiagram|classDiagram|stateDiagram(?:-v2)?|erDiagram|journey|gantt|pie|quadrantChart|requirementDiagram|gitGraph|mindmap|timeline|zenuml|sankey-beta|xychart-beta|block-beta|architecture-beta)\b/m.test(
      cleaned,
    )
  if (!hasHeader) {
    cleaned = `flowchart TD\n  ${cleaned}`
  }

  // 4. Auto-repair unquoted node labels with brackets/parentheses e.g. A[Login (User)] -> A["Login (User)"]
  // Matches A[something (with parens)] without existing double quotes
  cleaned = cleaned.replace(/\[([^[\]"']*\([^)]*\)[^[\]"']*)\]/g, '["$1"]')

  // 5. Syntax validation pass with mermaid.parse()
  try {
    const parseResult = await mermaid.parse(cleaned)
    if (!parseResult) {
      return {
        valid: false,
        code: cleaned,
        error: 'Mermaid parse returned false.',
      }
    }
    return { valid: true, code: cleaned }
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err)

    // Second-pass auto-heal attempt: if it failed, try escaping quotes or formatting
    try {
      const healed = cleaned.replace(/([A-Za-z0-9_]+)\[([^"\]]+)\]/g, '$1["$2"]')
      await mermaid.parse(healed)
      return { valid: true, code: healed }
    } catch {
      return {
        valid: false,
        code: cleaned,
        error: errMsg,
      }
    }
  }
}

/**
 * Validate and sanitize Draw.io XML:
 * 1. Strips any <script> tags or executable attributes (XSS guardrail)
 * 2. Parses via DOMParser to ensure well-formed XML
 * 3. Verifies essential Draw.io root structure (<mxfile> or <mxGraphModel> with root cells)
 */
export function validateAndSanitizeDrawio(rawXml: string): {
  valid: boolean
  xml: string
  error?: string
} {
  let cleaned = rawXml.trim()
  cleaned = cleaned.replace(/^```(?:xml|drawio)?\s*\n?/i, '')
  cleaned = cleaned.replace(/\n?```\s*$/i, '')
  cleaned = cleaned.trim()

  // Security sanitization: strip script tags and javascript: links
  cleaned = cleaned.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
  cleaned = cleaned.replace(/javascript\s*:/gi, 'about:blank#blocked')
  cleaned = cleaned.replace(/\son\w+\s*=\s*["'][^"']*["']/gi, '')

  if (!cleaned) {
    return { valid: false, xml: '', error: 'Empty Draw.io XML.' }
  }

  // XML well-formedness check
  try {
    const parser = new DOMParser()
    const doc = parser.parseFromString(cleaned, 'text/xml')
    const parseError = doc.querySelector('parsererror')
    if (parseError) {
      return {
        valid: false,
        xml: cleaned,
        error: `XML Malformed: ${parseError.textContent?.slice(0, 200)}`,
      }
    }

    // Verify root presence
    const hasModel = doc.querySelector('mxGraphModel')
    if (!hasModel) {
      return {
        valid: false,
        xml: cleaned,
        error: 'Missing <mxGraphModel> root element in Draw.io document.',
      }
    }

    return { valid: true, xml: cleaned }
  } catch (err) {
    return {
      valid: false,
      xml: cleaned,
      error: err instanceof Error ? err.message : String(err),
    }
  }
}

/**
 * Automatic layout collision avoidance:
 * Computes non-overlapping coordinates for newly generated nodes.
 */
export function layoutNodesWithoutOverlap(
  count: number,
  options?: {
    direction?: 'horizontal' | 'vertical' | 'grid'
    startX?: number
    startY?: number
    nodeWidth?: number
    nodeHeight?: number
    gapX?: number
    gapY?: number
    columns?: number
  },
): Array<{ x: number; y: number; width: number; height: number }> {
  const {
    direction = 'grid',
    startX = 100,
    startY = 80,
    nodeWidth = 140,
    nodeHeight = 60,
    gapX = 60,
    gapY = 50,
    columns = 3,
  } = options || {}

  const result: Array<{ x: number; y: number; width: number; height: number }> = []

  for (let i = 0; i < count; i++) {
    let x = startX
    let y = startY

    if (direction === 'horizontal') {
      x = startX + i * (nodeWidth + gapX)
    } else if (direction === 'vertical') {
      y = startY + i * (nodeHeight + gapY)
    } else {
      // grid
      const col = i % columns
      const row = Math.floor(i / columns)
      x = startX + col * (nodeWidth + gapX)
      y = startY + row * (nodeHeight + gapY)
    }

    result.push({ x, y, width: nodeWidth, height: nodeHeight })
  }

  return result
}
